from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT = 'BI_Taller6_Ocampo_Zapata.pdf'
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleBlack', parent=styles['Title'], textColor=colors.black, fontName='Helvetica-Bold', fontSize=22, leading=27, alignment=TA_CENTER, spaceAfter=18))
styles.add(ParagraphStyle(name='H1x', parent=styles['Heading1'], textColor=colors.black, fontName='Helvetica-Bold', fontSize=15, leading=19, spaceBefore=12, spaceAfter=7))
styles.add(ParagraphStyle(name='H2x', parent=styles['Heading2'], textColor=colors.black, fontName='Helvetica-Bold', fontSize=11.5, leading=14, spaceBefore=9, spaceAfter=5))
styles.add(ParagraphStyle(name='Bodyx', parent=styles['BodyText'], fontName='Helvetica', fontSize=9.0, leading=11.6, spaceAfter=5.5))
styles.add(ParagraphStyle(name='Smallx', parent=styles['BodyText'], fontName='Helvetica', fontSize=7.5, leading=9.2, spaceAfter=3))

def p(x, style='Bodyx'): return Paragraph(x, styles[style])
def table(headers, rows, widths=None, small=True):
    data=[[p(h,'Smallx') for h in headers]]+[[p(str(c),'Smallx' if small else 'Bodyx') for c in r] for r in rows]
    t=Table(data, colWidths=widths, repeatRows=1, hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17365D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#D9D9D9')),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F4F7FA')])]))
    return t
def foot(canvas, doc):
    canvas.saveState(); canvas.setFont('Helvetica',8); canvas.drawString(0.65*inch,0.42*inch,'SolarBI - Taller 6 - 2026-II'); canvas.drawRightString(7.85*inch,0.42*inch,f'Página {doc.page}'); canvas.restoreState()

doc=SimpleDocTemplate(OUT,pagesize=letter,rightMargin=.62*inch,leftMargin=.62*inch,topMargin=.62*inch,bottomMargin=.65*inch)
s=[]
s += [Spacer(1,1.25*inch),p('INSTITUCIÓN UNIVERSITARIA PASCUAL BRAVO','H2x'),p('Inteligencia de Negocios · Taller 6 · 2026-II','H2x'),Spacer(1,.35*inch),p('SolarBI','TitleBlack'),p('Solución de inteligencia de negocios contenerizada para una microrred híbrida','H2x'),Spacer(1,.25*inch),p('Autores: Alejandro Ocampo y Santiago Zapata','Bodyx'),p('Repositorio: <u>Completar con el enlace público de GitHub antes de entregar</u>','Bodyx'),p('Noviembre de 2026','Bodyx'),PageBreak()]
s += [p('Resumen ejecutivo','H1x'),p('SolarBI transforma la telemetría histórica de OpenCEM en indicadores sobre generación fotovoltaica, energía entregada a las cargas, importación de red y comportamiento de batería. La Bronze es la base SQLite oficial, inmutable y consultada en modo de solo lectura. El ETL aplica reglas físicas y produce una Silver horaria; PostgreSQL implementa el modelo dimensional Gold. Power BI se destina a la decisión histórica y Grafana a la operación y las alertas.'),p('<b>Resultado verificable:</b> sobre 2.989.759 lecturas de <i>analog_measurements</i>, el ETL produjo 14.076 filas horarias y minimizó 25.178 registros JSON de contexto. Docker Compose ejecutó PostgreSQL 16.4, el ETL, Grafana 11.2 y el simulador; se verificaron las claves únicas, el tablero provisionado, la fuente PostgreSQL y dos reglas de alerta. Kubernetes sigue pendiente porque Docker Desktop no tiene un contexto de clúster activo.'),p('1. Usuarios y preguntas de negocio','H1x'),table(['Usuario','Preguntas que responde'],[['Dirección de infraestructura','¿Cuánta energía aporta el sol? ¿Cuánto se compra a la red? ¿Dónde ampliar paneles o batería? ¿Cuál es el impacto en COP?'],['Mantenimiento','¿Qué inversor está en SoC crítico? ¿Llegan lecturas? ¿Hay eventos de baja disponibilidad?'],['TI y datos','¿La carga es reproducible, idempotente y segura? ¿El contexto conserva solo los datos necesarios?']],[1.5*inch,5.7*inch]),p('2. Insumos y preparación de datos','H1x'),p('La fuente es OpenCEM v1.0.0, publicada bajo CC BY 4.0. La Bronze usada es <i>opencem-v1.0.0.sqlite</i>; no se modifica ni se versiona en Git. El archivo de checksums entregado contiene el hash de la descarga comprimida. La descompresión reproducible es <font name="Courier">zstd -d opencem-v1.0.0.sqlite.zst -o opencem-v1.0.0.sqlite</font>. Antes de cargar, se recomienda ejecutar <font name="Courier">sha256sum -c opencem-v1.0.0-SHA256SUMS.txt</font> en la carpeta de descarga.'),table(['Tabla Bronze','Filas','Cobertura UTC','Uso en la solución'],[['analog_measurements','2.989.759','2025-07-12 a 2026-07-13','Telemetría eléctrica y Silver horaria'],['context','25.178','2024-07-27 a 2026-07-14','Contexto JSON minimizado'],['fault_history','2.129.517','2025-07-12 a 2026-07-13','Evolución: eventos y alarmas'],['settings','2.284.775','2025-07-12 a 2026-07-13','Parámetros operativos'],['statistics','2.285.904','2025-07-12 a 2026-07-13','Contrastes de energía'],['status / totals','2.240.052 / 2.279.918','2025-07-12 a 2026-07-13','Estado y totales del inversor']],[1.35*inch,.8*inch,2*inch,3.05*inch]),PageBreak()]
s += [p('3. Arquitectura y despliegue','H1x'),p('La solución adopta una arquitectura medallón y una constelación dimensional. Se prefirió estrella/constelación a copo de nieve porque las dimensiones son pequeñas, conformadas y se busca simplificar el consumo analítico.'),table(['Flujo extremo a extremo'],[['Bronze SQLite','ETL Python: limpieza, integración y minimización JSON','Silver: inversor-hora','PostgreSQL Gold','Power BI: histórico y escenarios'],['Bronze SQLite','ETL Python: limpieza, integración y minimización JSON','Silver: inversor-hora','PostgreSQL Gold','Grafana: estado y alertas']],[1.25*inch,1.75*inch,1.2*inch,1.25*inch,1.75*inch]),p('En Kubernetes el Namespace <i>solar-bi</i> aísla los recursos. PostgreSQL se despliega como StatefulSet con PVC para preservar datos; Grafana como Deployment porque su configuración y tablero son ConfigMaps provisionados. El Job ejecuta la carga histórica y el CronJob simula nuevas lecturas. Los Services dan DNS interno y NodePort para DBeaver/Power BI. Secret contiene contraseñas, ConfigMap contiene parámetros no sensibles; probes y requests/limits verifican salud y protegen el equipo anfitrión.'),table(['Necesidad','Objeto elegido','Justificación frente a alternativa'],[['Aislamiento','Namespace','Separa el proyecto de otros recursos; no se reemplaza por etiquetas.'],['Datos persistentes','StatefulSet + PVC','Identidad estable y volumen propio; Deployment no garantiza esa identidad.'],['Grafana disponible','Deployment','Carga sin estado y reiniciable; no requiere StatefulSet.'],['Secretos','Secret','Evita claves en imagen o Git; no ConfigMap.'],['Parámetros','ConfigMap','Umbrales e intervalos independientes del código.'],['Descubrimiento','Service','DNS por nombre, no IP efímera.'],['Carga histórica','Job','Termina y deja logs; no Deployment.'],['Datos nuevos','CronJob','Ejecución periódica controlada; no proceso ocioso.'],['Salud','Liveness/Readiness probes','Permite reinicio y evita tráfico prematuro.'],['Capacidad','Requests/Limits','Evita agotar nodo y explicita recursos.']],[1.25*inch,1.55*inch,4.65*inch]),p('Distribución escogida: Minikube de un nodo, por su uso directo en laboratorio. Las imágenes propias se construyen con <font name="Courier">docker build -t solarbi-etl:1.0 etl</font> y se cargan con <font name="Courier">minikube image load solarbi-etl:1.0</font>. Se fija Python 3.12 slim para el ETL, PostgreSQL 16.4-alpine y Grafana 11.2.0; no se usa <i>latest</i>.'),p('4. Modelo dimensional, grano y linaje','H1x'),table(['Proceso / tabla','Grano','Dimensiones y regla'],[['Batería histórica: fact_bateria_hora','Una fila por inversor y hora UTC','dim_inversor, dim_fecha, dim_estado_soc; UPSERT por clave compuesta.'],['Operación: fact_bateria_vivo','Una lectura simulada por inversor y marca de tiempo','Sirve series de tiempo y estado actual.'],['Contexto: fact_contexto_minimo','Un registro por id de contexto','Solo fuente, intervalo y duración; no texto libre.']],[1.7*inch,2.1*inch,3.65*inch]),p('La dimensión propia <i>dim_estado_soc</i> clasifica Crítico (0-20), Bajo (20-40), Medio (40-80) y Alto (80-100). Las jerarquías son fecha: año-mes-día e inversor: subsistema. Si cambian capacidad o paneles, dim_inversor deberá usar SCD tipo 2. Los episodios de SoC crítico son una vista gaps-and-islands: se modelan como eventos con inicio y fin, no como lecturas duplicadas.'),PageBreak()]
s += [p('5. ETL, calidad, reconciliación y ética','H1x'),p('Python se eligió porque incluye sqlite3, es portable en contenedor, permite pruebas automáticas y usa psycopg para PostgreSQL. La carga bloquea transacciones concurrentes y ejecuta <i>INSERT ... ON CONFLICT DO UPDATE</i>; por tanto, repetirla con la misma Bronze no duplica claves ni altera el resultado.'),table(['Regla','Efecto en Bronze real'],[['R1: SoC nulo/no numérico','809 filas excluidas en inversor 1 y 57.122 en inversor 2.'],['R2: SoC fuera de 0-100 o voltaje fuera de 10-80 V','767 filas excluidas en inversor 1 y 1.705 en inversor 2.'],['R4: hueco > 600 segundos','214 huecos en inversor 1 y 102 en inversor 2; no se inventa energía.'],['R5: banda muerta |I| <= 1 A','Evita contabilizar el offset de reposo como descarga.'],['Evento operativo real','SoC bajo no se elimina: alimenta el KPI y la vista de eventos.']],[2.45*inch,5*inch]),p('La agregación horaria baja el volumen y acelera Power BI/SQL; a cambio pierde picos de segundos. La tabla viva mantiene la granularidad operativa. La conciliación se comprueba comparando el total de lecturas válidas en <i>dw.etl_audit</i> con el conteo de reglas del ETL y comparando las horas UPSERT con el CSV Silver. El test automatizado valida decodificación de corriente, banda muerta, integración y huecos.'),p('El JSON de <i>context.value</i> se analiza en Bronze y se minimiza antes de Gold: se descarta <i>textual_description</i>, que puede contener información personal. Se retienen fuente, inicio, fin y duración para correlación operativa. Esta minimización aplica el principio de finalidad y necesidad de la Ley 1581 de 2012; el acceso se limita mediante rol de solo lectura y las credenciales viven en Secret, no en código.'),p('6. Catálogo de indicadores','H1x'),table(['Indicador','Fórmula y unidad','Granularidad','Fuente / usuario'],[['Energía solar generada','Integral de pv1power; kWh','inversor, día, mes, período','analog_measurements / Dirección'],['Energía a la carga','Integral de outsumw; kWh','inversor, día, mes, período','analog_measurements / Dirección'],['Importación de red','Integral max(gridpowerw_a,0); kWh','inversor, día, mes, período','analog_measurements / Dirección'],['SoC promedio y mínimo','Promedio ponderado / MIN; %','inversor, día, mes, período','battsoc / Mantenimiento'],['Disponibilidad y datos válidos','seg_obs/(seg_obs+seg_hueco); válidas/leídas; %','inversor, día, mes, período','read_ts + auditoría / Ambos'],['Ciclos equivalentes','kWh descarga / capacidad; ciclos','inversor, mes, período','derivado / Dirección'],['Autosuficiencia','1 - kWh red/kWh carga; %','inversor, mes, período','derivado / Dirección'],['Costo evitado','kWh descarga x tarifa; COP','inversor, mes, período','parámetro tarifa / Dirección']],[1.35*inch,2.1*inch,1.45*inch,2.55*inch]),p('La tarifa de 850 COP/kWh es un parámetro de escenario, no una afirmación de tarifa vigente: debe reemplazarse por una tarifa publicada por el comercializador aplicable al campus y citarse antes de la entrega. El Performance Ratio no es calculable con rigor porque falta irradiancia en el plano de los paneles; se recomienda piranómetro o irradiancia calibrada.'),PageBreak()]
s += [p('7. Resultados sobre la Bronze procesada','H1x'),table(['Inversor','SoC prom.','SoC mín.','Tiempo SoC<20','PV kWh','Carga kWh','Red kWh','Descarga kWh','Disponibilidad'],[['1','90,16 %','6 %','0,50 %','959,8','1.865,7','455,9','488,8','88,8 %'],['2','82,24 %','10 %','2,33 %','1.396,8','4.157,7','368,2','832,7','75,9 %']],[.65*inch,.7*inch,.6*inch,.8*inch,.65*inch,.75*inch,.65*inch,.85*inch,.85*inch]),p('El inversor 2 concentra más energía entregada a las cargas y más descarga de batería, además de pasar 2,33 % del tiempo observado bajo 20 % de SoC. Esto prioriza revisar su capacidad o desplazar cargas. El inversor 1 presenta menor energía de carga pero también un mínimo de 6 %, por lo que ambos requieren alertas. La disponibilidad inferior a 95 % impide tratar las integrales como facturación; se reporta explícitamente como limitación.'),p('8. Evidencia real de Docker, PostgreSQL y Grafana','H1x'),table(['Componente','Evidencia verificada','Resultado'],[['PostgreSQL 16.4','Contenedor healthy; puerto local 5433','Esquema Gold creado y accesible.'],['ETL','Dos ejecuciones consecutivas contra la Bronze','14.076 filas horarias y 14.076 claves únicas: carga idempotente.'],['Contexto JSON','ETL de minimización','25.178 filas Gold; textual_description excluido.'],['Simulador','Contenedor activo, intervalo 5 s','Inserta lecturas nuevas de SoC para ambos inversores.'],['Grafana 11.2','API /api/health y provisioning','Fuente PostgreSQL, dashboard SolarBI y 2 alertas provisionados.']],[1.35*inch,3.1*inch,2.75*inch]),p('El DDL define restricciones, PK/FK, un BRIN temporal y la vista de eventos. Las consultas anexas incluyen LAG para variación mensual, RANK de días de mayor descarga, SUM OVER acumulado y consulta nativa JSONB: <font name="Courier">detalle ? ''atributo_excluido''</font> sobre la auditoría. DBeaver se conecta al puerto 5433, no a archivos.'),p('Grafana quedó publicado en <font name="Courier">http://localhost:3001</font>, ya que el puerto 3000 estaba ocupado. La API confirmó el tablero <i>SolarBI - Estado de batería</i>, la fuente de datos PostgreSQL en modo lectura y dos alertas provisionadas desde archivo: SoC crítico menor a 20 % y ausencia de lecturas por más de 3 minutos. Power BI conserva el formato PBIP y necesita abrirse para tomar las tres capturas de interfaz exigidas.'),p('9. Evidencia de Kubernetes y Power BI aún pendiente','H1x'),p('No se ejecutó Kubernetes porque el contexto de kubectl no está configurado en Docker Desktop. Por integridad académica, no se incluyen capturas ficticias. Antes de la sustentación se debe activar Kubernetes en Docker Desktop o crear un clúster Minikube, ejecutar el kustomize y anexar: (1) <font name="Courier">kubectl get all -n solar-bi</font>; (2) <font name="Courier">kubectl describe</font>; (3) recuperación de PostgreSQL y Grafana tras borrar sus pods; y (4) tres páginas de Power BI, modelo y medidas DAX.'),PageBreak()]
s += [p('10. Reproducibilidad, resiliencia y conclusiones','H1x'),p('Para levantar: crear <i>k8s/secret.env</i> desde la plantilla, construir y cargar la imagen en Minikube, montar la carpeta que contiene la SQLite Bronze y ejecutar <font name="Courier">kubectl apply -k k8s</font>. Para eliminar: <font name="Courier">kubectl delete namespace solar-bi</font>. PostgreSQL no se escala horizontalmente porque un único volumen RWO contiene su estado; Grafana sí puede escalar porque tablero, datasource y reglas se provisionan desde ConfigMaps.'),p('Prueba de resiliencia: eliminar <font name="Courier">postgres-0</font>, esperar el StatefulSet y verificar que el PVC y el conteo Gold permanecen; eliminar el pod de Grafana y comprobar que el Deployment lo recrea con su dashboard provisionado. Para una demostración de streaming, activar <font name="Courier">SIM_TRIGGER=1</font> en el CronJob y observar nueva lectura y alerta.'),p('Conclusiones','H2x'),p('La solución corrige el alcance del módulo inicial: incorpora energía solar, carga, red y batería; usa la SQLite como Bronze; integra el JSON con minimización verificable y deja artefactos reproducibles para PostgreSQL, Power BI, Grafana y Kubernetes. El hallazgo operativo principal es el mayor estrés del inversor 2 y una disponibilidad de registro menor al objetivo. La prioridad es ejecutar la demostración local y adjuntar sus capturas sin modificar los hechos ya medidos.'),p('Referencias','H1x'),p('Bartels, T. S., Wu, R., Lu, X., Chen, Y., Lu, Y., Xia, F., Yang, H., Chen, Y., & Li, T. (2026). <i>OpenCEM: Multimodal photovoltaic and battery microgrid dataset with context records and sky imagery</i> (Version 1.0.0) [Dataset]. Zenodo. https://doi.org/10.5281/zenodo.21436223.'),p('Congreso de Colombia. (2012). Ley Estatutaria 1581 de 2012, por la cual se dictan disposiciones generales para la protección de datos personales.')]
s += [p('Anexo A Evidencia reproducible de la ejecución','H1x'),table(['Prueba','Comando / criterio','Resultado observado'],[['Carga histórica','docker compose run --rm etl','ETL terminó sin errores; cargó telemetría y contexto.'],['Idempotencia','Segunda ejecución + COUNT y DISTINCT clave','14.076 filas y 14.076 claves únicas.'],['Conciliación','Consulta a fact_bateria_hora','PV: 959,8/1.396,8 kWh; carga: 1.865,7/4.157,7 kWh.'],['Salud Grafana','GET /api/health','database: ok; versión 11.2.0.'],['Provisioning Grafana','API de búsqueda, datasource y alert-rules','Dashboard SolarBI, datasource solarbi-pg, 2 alertas con procedencia file.']],[1.35*inch,3.5*inch,2.35*inch]),p('Esta evidencia es repetible desde el repositorio con Docker Desktop. Para completar el componente Kubernetes es necesario habilitar su clúster local y volver a capturar los comandos de control. La entrega debe sustituir el marcador de la portada por el enlace GitHub real y conservar únicamente los dos autores que correspondan a la modalidad.'),p('Anexo B Guion de sustentación','H1x'),table(['Momento','Demostración'],[['1. Fuente y calidad','Mostrar SQLite Bronze, checksum, inventario y reglas R1-R5.'],['2. Datos a decisión','Consultar PostgreSQL, explicar grano y comparar inversores.'],['3. Operación','Abrir Grafana en localhost:3001 y evidenciar simulador/alertas.'],['4. Analítica','Abrir PBIP, navegar las tres páginas y variar tarifa/capacidad.'],['5. Resiliencia','En el clúster, borrar un pod y comprobar PVC/provisioning.']],[1.6*inch,5.6*inch]),p('Este guion conecta la historia de datos con la decisión: el inversor 2 concentra el mayor uso de batería y mayor exposición a SoC bajo; la disponibilidad de registros queda bajo el objetivo y debe corregirse antes de convertir estas integrales en costos facturables.')]
doc.build(s,onFirstPage=foot,onLaterPages=foot)
print(OUT)
